readonly struct Money(decimal amount, string currency)
{
    public decimal Amount { get; } = amount;
    public string Currency { get; } = currency;

    public static Money operator +(Money left, Money right)
    {
        if (left.Currency != right.Currency)
            throw new InvalidOperationException("currency mismatch");
        return new Money(left.Amount + right.Amount, left.Currency);
    }
}

var total = new Money(10, "USD") + new Money(5, "USD");

struct RunningTotal
{
    public decimal Amount;

    public void operator +=(decimal delta) => Amount += delta;
    public void operator -=(decimal delta) => Amount -= delta;
}

var total = new RunningTotal();
total += 10.5m;
total += 3.0m;
// total.Amount is 13.5 — updated in place, no copy

// BAD: implicit string conversion hides parsing failures
// public static implicit operator AuthToken(string raw)
//     => new AuthToken(Parse(raw));

// GOOD: explicit factory with clear error handling
public readonly struct AuthToken
{
    public string Value { get; }
    private AuthToken(string value) => Value = value;

    public static bool TryCreate(string raw, out AuthToken token)
    {
        if (string.IsNullOrWhiteSpace(raw)) { token = default; return false; }
        token = new AuthToken(raw);
        return true;
    }
}
